styles.css:
display: inline-flex;
align-items: center;
justify-content: center;
align-self: flex-start;
min-inline-size: 5rem;
min-block-size: 5rem;
box-sizing: border-box;
overflow: hidden;
line-height: 0;
--ls-icon-frame-accent-colour: var(--ls-card-solutions-accent-colour, var(--wp--custom--color--card--solutions--brand));
--ls-icon-frame-shadow-active: 0 0 4px 4px color-mix(in srgb, var(--ls-icon-frame-accent-colour) 50%, transparent);
--ls-icon-frame-inset-shadow-active: inset 0 0 4px 3px color-mix(in srgb, var(--ls-icon-frame-accent-colour) 50%, transparent);
--ls-icon-frame-tilt: -3deg;
border-color: var(--ls-icon-frame-accent-colour);
background: color-mix(in srgb, var(--ls-icon-frame-accent-colour) 10%, transparent);

& .wp-block-outermost-icon-block {
	display: flex;
	align-items: center;
	justify-content: center;
	flex: 0 0 auto;
	margin: 0;
	line-height: 0;
	color: var(--ls-icon-frame-accent-colour);
}

& .icon-container {
	display: inline-flex;
	align-items: center;
	justify-content: center;
	background: transparent !important;
	color: var(--ls-icon-frame-accent-colour) !important;
}

& .icon-container svg {
	fill: currentColor;
}
